const RUST = 'references/rust-2020-fiji-vascular-analysis';
const cleanLibrary = [
  `${RUST}/digest.md`,
  `${RUST}/rust-2020-fiji-vascular-analysis.pdf`,
  `${RUST}/supplementary/Quantification.ijm`,
